UPDATE reports SET bathroom_target_id = target_id WHERE target_type = 'BATHROOM';
UPDATE reports SET review_target_id = target_id WHERE target_type = 'REVIEW';
UPDATE reports SET bathroom_image_target_id = target_id WHERE target_type = 'PHOTO' AND EXISTS (SELECT 1 FROM bathroom_images i WHERE i.image_id = reports.target_id);
UPDATE reports SET review_image_target_id = target_id WHERE target_type = 'PHOTO' AND EXISTS (SELECT 1 FROM review_images i WHERE i.image_id = reports.target_id);
ALTER TABLE reports ADD CONSTRAINT reports_target_fk_check CHECK ((target_type = 'BATHROOM' AND bathroom_target_id IS NOT NULL AND bathroom_target_id = target_id AND review_target_id IS NULL AND bathroom_image_target_id IS NULL AND review_image_target_id IS NULL) OR (target_type = 'REVIEW' AND review_target_id IS NOT NULL AND review_target_id = target_id AND bathroom_target_id IS NULL AND bathroom_image_target_id IS NULL AND review_image_target_id IS NULL) OR (target_type = 'PHOTO' AND bathroom_image_target_id IS NOT NULL AND bathroom_image_target_id = target_id AND bathroom_target_id IS NULL AND review_target_id IS NULL AND review_image_target_id IS NULL) OR (target_type = 'PHOTO' AND review_image_target_id IS NOT NULL AND review_image_target_id = target_id AND bathroom_target_id IS NULL AND review_target_id IS NULL AND bathroom_image_target_id IS NULL));
